class MyntException(val status: Int, val code: String, message: String) : Exception(message)

/** sha256:<hex> of the exact text you showed, so the evidence proves what was on screen. */
fun hashText(text: String): String =
    "sha256:" + MessageDigest.getInstance("SHA-256").digest(text.toByteArray(Charsets.UTF_8)).joinToString("") { String.format("%02x", it) }

class MyntClient(private val clientSecret: String, private val baseUrl: String = DEFAULT_BASE_URL) {
    init {
        require(!Regex("^mynt_(live|test)_").containsMatchIn(clientSecret)) { "That's an app key: keep it on your server and send the device a client session secret instead" }
        require(Regex("^mcs_(live|test)_").containsMatchIn(clientSecret)) { "clientSecret must be a mcs_live_ or mcs_test_ client session secret" }
    }

    private fun request(method: String, path: String, body: JSONObject? = null): JSONObject {
        val conn = URL(baseUrl.trimEnd('/') + path).openConnection() as HttpURLConnection
        conn.requestMethod = method
        conn.setRequestProperty("Authorization", "Bearer " + clientSecret)
        conn.setRequestProperty("Accept", "application/json")
        if (body != null) {
            conn.doOutput = true
            conn.setRequestProperty("Content-Type", "application/json")
            conn.outputStream.use { it.write(body.toString().toByteArray(Charsets.UTF_8)) }
        }
        val status = conn.responseCode
        val stream = if (status in 200..299) conn.inputStream else conn.errorStream
        val text = stream?.bufferedReader()?.use { it.readText() } ?: ""
        val json = if (text.isBlank()) JSONObject() else JSONObject(text)
        if (status !in 200..299) throw MyntException(status, json.optString("error", "http_" + status), json.optString("message", "HTTP " + status))
        return json
    }

    private fun evidence(productId: String, type: String, subject: String, contentHash: String?): JSONObject {
        val body = JSONObject().put("product_id", productId).put("type", type).put("subject", subject)
        if (contentHash != null) body.put("content_hash", contentHash)
        return request("POST", "/client/evidence", body)
    }

    /** The session's products: offers per segment, documents to show, consents and startable actions. */
    fun offers(): JSONObject = request("GET", "/client/offers")

    /** Records that a required document was shown, with a hash of the exact text. */
    fun documentShown(productId: String, document: String, shownText: String): JSONObject {
        require(MyntContract.DOCUMENTS[productId]?.contains(document) == true) { document + " isn't a document of " + productId }
        return evidence(productId, "disclosure_shown", document, hashText(shownText))
    }

    /** Records the customer's consent for a purpose (needed before actions that use their data). */
    fun giveConsent(productId: String, purpose: String, consentText: String): JSONObject {
        require(MyntContract.CONSENT_PURPOSES[productId]?.contains(purpose) == true) { purpose + " isn't a consent purpose of " + productId }
        return evidence(productId, "consent_given", purpose, hashText(consentText))
    }

    fun withdrawConsent(productId: String, purpose: String): JSONObject = evidence(productId, "consent_withdrawn", purpose, null)

    /** Starts a provider-hosted action; send the customer to redirect_url. */
    fun startAction(productId: String, action: String): JSONObject {
        require(MyntContract.CLIENT_ACTIONS[productId]?.contains(action) == true) { action + " isn't a client action of " + productId }
        return request("POST", "/client/actions/" + action, JSONObject().put("product_id", productId))
    }

    /** Stores customer data the product's actions need. Sensitive fields must come from a secure input. */
    fun saveFields(productId: String, values: Map<String, Any>, source: String = "typed"): JSONObject =
