/** What the customer did on a step. */
class StepInput(
    val documents: Map<String, String> = emptyMap(),
    val fields: Map<String, Any> = emptyMap(),
    val consentText: String? = null,
    val outcome: String? = null,
)

/**
 * A headless journey runner: render [current] however you like, then call [complete] with what the
 * customer did. It records document and consent evidence, stores fields, prefills, starts hosted actions
 * (returning where to send the customer) and follows the journey's branches.
 */
class JourneyRunner(private val client: MyntClient, journeyId: String) {
    val journey: JSONObject = client.journey(journeyId)
    private val product: String = journey.getJSONObject("built_on").getString("product_id")
    private val steps: Map<String, JSONObject>
    var current: JSONObject?
        private set

    init {
        val list = journey.getJSONArray("steps")
        steps = (0 until list.length()).map { list.getJSONObject(it) }.associateBy { it.getString("id") }
        current = if (list.length() > 0) list.getJSONObject(0) else null
    }

    val done: Boolean
        get() {
            val s = current ?: return true
            return !s.has("next") && !s.has("on") && !s.has("action") && !s.has("capture_consent") && !s.has("await_event")
        }

    private fun go(id: String?) {
        current = if (id == null) null else steps[id]
    }

    private fun branch(step: JSONObject, outcome: String?): String? {
        val on = step.optJSONObject("on")
        if (outcome != null && on != null && on.has(outcome)) return on.getString(outcome)
        return if (step.has("next")) step.getString("next") else null
    }

    /** Completes the current step; for a hosted action, returns where to send the customer. */
    fun complete(input: StepInput = StepInput()): String? {
        val step = current ?: throw IllegalStateException("The journey has ended")
        if (step.has("capture_consent")) {
            val text = input.consentText ?: throw IllegalArgumentException("Pass the consent wording the customer agreed to")
            client.giveConsent(product, step.getString("capture_consent"), text)
            go(branch(step, null))
            return null
        }
        if (step.has("action")) {
            if (input.outcome != null) {
                go(branch(step, input.outcome))
                return null
            }
            val started = client.startAction(product, step.getString("action"))
            return if (started.has("redirect_url")) started.getString("redirect_url") else null
        }
        if (step.has("await_event")) {
            go(branch(step, input.outcome))
            return null
        }
        val screen = step.optJSONArray("screen") ?: JSONArray()
        val elements = (0 until screen.length()).map { screen.getJSONObject(it) }
        for (e in elements.filter { it.getString("type") == "disclosure" }) {
            val document = e.getString("document")
            val text = input.documents[document] ?: throw IllegalArgumentException("Pass the text shown for document " + document)
            client.documentShown(product, document, text)
        }
        val fields = elements.filter { it.getString("type") == "field" }
        for (source in listOf("typed", "secure_field", "document_upload")) {
            val values = fields.filter { it.optString("capture", "typed") == source && input.fields.containsKey(it.getString("field")) }
                .associate { it.getString("field") to input.fields.getValue(it.getString("field")) }
            if (values.isNotEmpty()) client.saveFields(product, values, source)
        }
        for (source in listOf("account_aggregator", "digilocker", "ckyc")) {
            val wanted = fields.filter { it.optString("capture") == source && !input.fields.containsKey(it.getString("field")) }.map { it.getString("field") }
            if (wanted.isNotEmpty()) client.prefill(product, source, wanted)
        }
        go(branch(step, input.outcome))
        return null
    }
}
